import { ThinkingBlock } from './ThinkingBlock'
import { useEffect, useRef, useState } from 'react'
import { CodeBlock } from './CodeBlock'
import { SummaryBlock } from './blocks/SummaryBlock'
import { useBoolVariation } from '@launchdarkly/react-native-client-sdk'
import { ThinkingType } from '../utils/llm-tags'

const PLACEHOLDER_INTERVAL = 2500

const placeHolderText = [
	'Initializing new document...',
	'Setting up file structure...',
	'Building framework...',
	'Processing requirements...',
	'Flowing words onto page...',
	'Thinking deeply...',
	'Analyzing context...',
	'Enhancing clarity...',
	'Smoothing rough edges...',
	'Fine-tuning details...'
]

export interface UIBlockData {
	uiType: string
	thinkingType?: string
	text?: string
	code?: string
	subtext?: string
	status?: string
	domains?: string
	secrets?: string[]
	browserLiveUrl?: string
	browserReplayUrl?: string
	browserSize?: string
	browserCurrentUrl?: string
	updates?: { device: 'mobile' | 'web'; url: string }[]
}

interface UIBlockProps {
	data: UIBlockData
	isLatest: boolean
	isLoading: boolean
	shouldAnimate: boolean
	isOnlyBlock: boolean
	messageId: string
	isLauncher: boolean
}

export const UIBlock = ({
	data,
	isLatest,
	isLoading,
	shouldAnimate,
	isOnlyBlock,
	messageId,
	isLauncher
}: UIBlockProps) => {
	const [currentPlaceholderIndex, setCurrentPlaceholderIndex] = useState(0)
	const prevLoadingRef = useRef(isLoading)
	const summaryBlockEnabled = useBoolVariation('summary-block-enabled', false)

	useEffect(() => {
		if (!isLoading) {
			prevLoadingRef.current = false
			return
		}

		if (!prevLoadingRef.current) {
			setCurrentPlaceholderIndex(0)
			prevLoadingRef.current = true
		}

		const interval = setInterval(() => {
			setCurrentPlaceholderIndex((prev) =>
				Math.min(prev + 1, placeHolderText.length - 1)
			)
		}, PLACEHOLDER_INTERVAL)

		return () => clearInterval(interval)
	}, [isLoading])

	if (data.thinkingType === ThinkingType.SCREENSHOT) {
		return null
	}

	if (data.uiType === 'thinking') {
		// shows indicator along with header text
		return (
			<ThinkingBlock
				text={data.text ?? ''}
				subtext={data.subtext ?? ''}
				status={data.status ?? ''}
				isLatest={isLatest}
				domains={data.domains ?? ''}
				thinkingType={data.thinkingType ?? ''}
				shouldAnimate={shouldAnimate}
				isOnlyBlock={isOnlyBlock}
				messageId={messageId}
			/>
		)
	}

	if (data.uiType === 'summary') {
		if (summaryBlockEnabled) {
			return (
				<SummaryBlock
					updates={data.updates ?? []}
					isLatest={isLatest}
					messageId={messageId}
					isLauncher={isLauncher}
				/>
			)
		}
		return null
	}

	return (
		<CodeBlock
			data={data}
			isLoading={isLoading}
			placeHolderText={placeHolderText}
			currentPlaceholderIndex={currentPlaceholderIndex}
		/>
	)
}
